+  size_t i;
+  uint32_t hash = UINT32_C(0x811c9dc5);
+  int ret;
+  if (out == NULL)
+    {
+      return UMCA_ERR_INVALID_ARG;
+    }
+  ret = umca_topic_validate(name, length);
+  if (ret != UMCA_OK)
+    {
+      return ret;
+    }
+  for (i = 0; i < length; i++)
+    {
+      hash ^= (uint8_t)name[i];
+      hash *= UINT32_C(0x01000193);
+    }
+  if (hash == UMCA_SYSTEM_TOPIC_ID)
+    {
+      return UMCA_ERR_TOPIC_COLLISION;
+    }
