}

static int tool_device_control(const char *input, char *output,
                               size_t output_size)
{
  bool on;
  if (g_adapter == NULL || input == NULL || output == NULL)
    {
      return -1;
    }
  if (strstr(input, "\"command\":\"on\"") != NULL)
    {
      on = true;
    }
  else if (strstr(input, "\"command\":\"off\"") != NULL)
    {
      on = false;
    }
  else
